// Canvas Catch game
// Canvas element with id "game" must exist in the HTML.

const canvas = document.getElementById('game');
if (!canvas) {
  throw new Error('Canvas element with id "game" not found');
}
const ctx = canvas.getContext('2d');

// Resize canvas to fill its container
function resize() {
  const rect = canvas.getBoundingClientRect();
  canvas.width = rect.width;
  canvas.height = rect.height;
}
window.addEventListener('resize', resize);
resize();

// Game state
let player = { x: canvas.width / 2, y: canvas.height - 30, radius: 15, speed: 5 };
let stars = [];
let score = 0;
let highScore = Number(localStorage.getItem('highScore')) || 0;
let gameOver = false;

// Input handling (arrow keys / WASD)
const keys = {};
window.addEventListener('keydown', e => { keys[e.key] = true; });
window.addEventListener('keyup', e => { keys[e.key] = false; });

function spawnStar() {
  const radius = 8 + Math.random() * 8;
  const x = Math.random() * (canvas.width - radius * 2) + radius;
  const speed = 1 + Math.random() * 2;
  stars.push({ x, y: -radius, radius, speed });
}
setInterval(spawnStar, 1000);

function update() {
  if (gameOver) return;
  if (keys.ArrowLeft || keys.a) player.x -= player.speed;
  if (keys.ArrowRight || keys.d) player.x += player.speed;
  player.x = Math.max(player.radius, Math.min(canvas.width - player.radius, player.x));
  for (let i = stars.length - 1; i >= 0; i--) {
    const s = stars[i];
    s.y += s.speed;
    const dx = s.x - player.x;
    const dy = s.y - player.y;
    const dist = Math.hypot(dx, dy);
    if (dist < s.radius + player.radius) {
      score++;
      stars.splice(i, 1);
      continue;
    }
    if (s.y - s.radius > canvas.height) {
      gameOver = true;
      if (score > highScore) {
        highScore = score;
        localStorage.setItem('highScore', highScore);
      }
      break;
    }
  }
}

function draw() {
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = '#0f0';
  ctx.beginPath();
  ctx.arc(player.x, player.y, player.radius, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#ff0';
  stars.forEach(s => {
    ctx.beginPath();
    ctx.arc(s.x, s.y, s.radius, 0, Math.PI * 2);
    ctx.fill();
  });
  ctx.fillStyle = '#fff';
  ctx.font = '16px sans-serif';
  ctx.fillText(`Score: ${score}`, 10, 20);
  ctx.fillText(`High: ${highScore}`, 10, 40);
  if (gameOver) {
    ctx.fillStyle = 'rgba(0,0,0,0.7)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#f00';
    ctx.textAlign = 'center';
    ctx.font = '32px sans-serif';
    ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
  }
}

function loop() {
  update();
  draw();
  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);
}
